import os

paths = ['/tmp/events.csv']
for p in paths:
    print(p, 'exists:', os.path.exists(p))

for d in ['/tmp', '.', '/mnt/data', os.path.expanduser('~')]:
    if os.path.isdir(d):
        try:
            files = os.listdir(d)
        except Exception as e:
            print(d, 'error:', e); continue
        matches = [f for f in files if 'event' in f.lower() or f.lower().endswith('.csv')]
        print(f"\n{d}: {len(files)} entries; candidates -> {matches[:20]}")

try:
    df_try = read_df('/tmp/events.csv')
